import React, { useState } from 'react';
import axios from 'axios';

function AgentModal({
  agent,
  purchased,
  accessStatus,
  authToken,
  apiBase,
  onClose,
  onLoadAgents
}) {
  const [question, setQuestion] = useState('');
  const [response, setResponse] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [showPurchasePrompt, setShowPurchasePrompt] = useState(false);
  const [purchaseLoading, setPurchaseLoading] = useState(false);
  const [purchaseSuccess, setPurchaseSuccess] = useState(null);
  const [showAccessDetails, setShowAccessDetails] = useState(false);
  const [accessDetails, setAccessDetails] = useState(null);
  const [loadingAccessDetails, setLoadingAccessDetails] = useState(false);

  const copyToClipboard = async (text) => {
    try {
      await navigator.clipboard.writeText(text);
      alert('Copied to clipboard');
    } catch {
      alert('Copy failed. Please copy manually.');
    }
  };

  const handleAsk = async (e) => {
    e.preventDefault();
    if (!question.trim()) return;

    setError('');
    setResponse('');
    setLoading(true);

    try {
      const res = await axios.post(
        `${apiBase}/agents/${agent.id}/ask`,
        { question: question.trim() },
        {
          headers: {
            Authorization: `Bearer ${authToken}`,
            'Content-Type': 'application/json'
          }
        }
      );

      setResponse(res.data.response);
      setQuestion('');
      onLoadAgents();
    } catch (err) {
      if (err.response?.status === 402) {
        setShowPurchasePrompt(true);
        setError('Demo limit reached! Please purchase to continue.');
        onLoadAgents();
      } else {
        setError(err.response?.data?.detail || 'Error asking agent');
      }
    } finally {
      setLoading(false);
    }
  };

  const handlePurchase = async () => {
    setPurchaseLoading(true);
    setError('');
    try {
      const res = await axios.post(
        `${apiBase}/agents/${agent.id}/purchase`,
        {},
        {
          headers: {
            Authorization: `Bearer ${authToken}`,
            'Content-Type': 'application/json'
          }
        }
      );

      setPurchaseSuccess({
        message: res.data.message,
        url: res.data.url,
        accessKey: res.data.access_key,
        purchasedAt: res.data.purchased_at
      });
      setShowPurchasePrompt(false);
      onLoadAgents();
    } catch (err) {
      setError(err.response?.data?.detail || 'Error purchasing agent');
    } finally {
      setPurchaseLoading(false);
    }
  };

  const handleShowAccessDetails = async () => {
    setLoadingAccessDetails(true);
    setError('');
    try {
      const res = await axios.get(
        `${apiBase}/agents/${agent.id}/access-details`,
        {
          headers: {
            Authorization: `Bearer ${authToken}`,
            'Content-Type': 'application/json'
          }
        }
      );
      console.log('Access Details Response:', res.data);
      setAccessDetails({
        url: res.data.url,
        accessKey: res.data.access_key,
        example_queries: res.data.example_queries || []
      });
      setShowAccessDetails(true);
    } catch (err) {
      console.error('Error fetching access details:', err);
      setError(err.response?.data?.detail || 'Error fetching access details');
    } finally {
      setLoadingAccessDetails(false);
    }
  };

  const demoUsesLeft = accessStatus.demo_uses_left || 0;
  const isPurchased = accessStatus.is_purchased;

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-content" onClick={(e) => e.stopPropagation()}>
        <div className="modal-top-row">
          <div>
            <h2 className="modal-agent-title">{agent.name}</h2>
            <p className="modal-agent-subtitle">
              {isPurchased ? (
                <span className="owned-text">✓ Owned</span>
              ) : (
                <span className="demo-text">Demo: {demoUsesLeft} try{demoUsesLeft !== 1 ? 'ies' : ''} left</span>
              )}
            </p>
          </div>
          <div className="modal-actions-top">
            {isPurchased && !purchaseSuccess && !showAccessDetails && (
              <button
                className="btn btn-success"
                onClick={handleShowAccessDetails}
                disabled={loadingAccessDetails}
              >
                {loadingAccessDetails ? 'Loading...' : 'Access Details'}
              </button>
            )}
            {!isPurchased && !purchaseSuccess && (
              <button
                className="btn btn-primary"
                onClick={handlePurchase}
                disabled={purchaseLoading}
              >
                {purchaseLoading ? '...' : 'Buy Now'}
              </button>
            )}
            <button onClick={onClose} className="close-btn" type="button">
              ✕
            </button>
          </div>
        </div>

        <p className="modal-description">{agent.description}</p>

        <div className="modal-panel">
          <h4 className="modal-panel-title">Purpose</h4>
          <p className="modal-panel-content">{agent.purpose}</p>
        </div>

        <div className="modal-panel">
          <h4 className="modal-panel-title">Capabilities</h4>
          <div className="capabilities">
            {agent.capabilities.map((cap, idx) => (
              <span key={idx} className="capability-badge">
                {cap}
              </span>
            ))}
          </div>
        </div>

        <div className="modal-panel">
          <h4 className="modal-panel-title">Status</h4>
          <div className="modal-status-row">
            <div>
              <span className="muted-text">Operational: </span>
              <span className="owned-text">{agent.status}</span>
            </div>
            <div>
              {isPurchased ? (
                <span className="owned-text">✓ Owned</span>
              ) : (
                <span className="demo-text">Demo: {demoUsesLeft} try{demoUsesLeft !== 1 ? 'ies' : ''} left</span>
              )}
            </div>
          </div>
        </div>

        {showAccessDetails && accessDetails ? (
          <div className="state-card state-success">
            <h4>✓ Agent Access Details</h4>
            <div className="code-block">
              <p className="code-label">Access URL:</p>
              <p>{accessDetails.url}</p>
              <p className="code-meta">
                Access Key: {accessDetails.accessKey}
              </p>
            </div>
            
            {accessDetails.example_queries && accessDetails.example_queries.length > 0 ? (
              <div className="info-block">
                <p className="info-title">Example Queries by Domain:</p>
                <ul className="query-list">
                  {accessDetails.example_queries.map((query, idx) => (
                    <li key={idx}>
                      {query}
                    </li>
                  ))}
                </ul>
              </div>
            ) : (
              <div className="info-block muted-text">
                No example queries available yet
              </div>
            )}
            
            <button className="btn btn-primary" onClick={() => copyToClipboard(accessDetails.url)} type="button">
              Copy URL
            </button>
            <button className="btn btn-ghost" onClick={() => setShowAccessDetails(false)} type="button">
              Close
            </button>
          </div>
        ) : showPurchasePrompt ? (
          <div className="state-card state-warn">
            <h4>Demo Limit Reached</h4>
            <p>
              You've used all your demo tries for this agent. Purchase now for unlimited access!
            </p>
            <button
              className="btn btn-primary"
              onClick={handlePurchase}
              disabled={purchaseLoading}
            >
              {purchaseLoading ? 'Processing...' : 'Purchase Now'}
            </button>
          </div>
        ) : purchaseSuccess ? (
          <div className="state-card state-success">
            <h4>✓ Purchase Successful!</h4>
            <p>
              <strong>Agent:</strong> {agent.name}
            </p>
            <p>
              <strong>Purchased:</strong> {new Date(purchaseSuccess.purchasedAt).toLocaleString()}
            </p>
            <div className="code-block">
              <p className="code-label">Access URL:</p>
              <p>{purchaseSuccess.url}</p>
              <p className="code-meta">
                Access Key: {purchaseSuccess.accessKey}
              </p>
            </div>
            <button className="btn btn-primary" onClick={() => copyToClipboard(purchaseSuccess.url)} type="button">
              Copy URL
            </button>
            <p className="purchase-note">
              You can now ask unlimited questions! Start typing below or use the URL with your access key.
            </p>
          </div>
        ) : null}

        {!purchaseSuccess && !showAccessDetails && (
          <form onSubmit={handleAsk} className="ask-form">
            <div className="form-group">
              <label className="form-label">
                Ask a question:
              </label>
              <textarea
                value={question}
                onChange={(e) => setQuestion(e.target.value)}
                disabled={loading || (!isPurchased && demoUsesLeft === 0)}
                className="form-textarea"
                placeholder="Type your question here..."
              />
            </div>
            <button
              type="submit"
              disabled={loading || !question.trim() || (!isPurchased && demoUsesLeft === 0)}
              className="btn btn-primary"
            >
              {loading ? 'Asking...' : 'Ask Agent'}
            </button>
          </form>
        )}

        {error && (
          <div className="state-card state-warn">
            {error}
          </div>
        )}

        {response && (
          <div className="state-card state-response">
            <h4>Response</h4>
            <p className="response-text">{response}</p>
          </div>
        )}
      </div>
    </div>
  );
}

export default AgentModal;
